INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Erina to Kima no Miyako', 'Erina, an engineer and a self-proclaimed adventurer, finds herself in Era Sheila after wandering from place to place fulfilling requests in pursuance of the romantic adventuring dream. The city is named after a famous adventurer, who happens to be one of Erina''s aspirations as an adventurer herself. Little did she know, the city had another moniker, widely known as the City of Machines. Just what does this city, one full of sex-starved men, have in store for Erina?' FROM games WHERE igdb_id = 304137 ON CONFLICT (game_id, language_code) DO NOTHING;
