INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Life on Earth: Reimagined', 'Life on Earth: Reimagined is a run-and-gun action/platform game released in 2023 by Kai Magazine Software. It combines fast-paced side-scrolling combat with influences from Contra, Shinobi 3, and Rolling Thunder. The game features three difficulty settings, plus Arcade and Heroic modes, and includes a cyberpunk setting with music by Savaged Regime.' FROM games WHERE igdb_id = 277552 ON CONFLICT (game_id, language_code) DO NOTHING;
