INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yandere-tensei-i-cant-beat-the-programming', 321421, '2023-08-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co909r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3ik4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yandere Tensei: I Can''t Beat The Programming!', 'Mei (name changeable) is an overworked office worker at a black company, who suddenly collapses on the office floor just as she''s about to head home after a late night. As she laments her fate and thinks about the bright side of dying at work (enjoy the stigma of working an employee to death, company!), her only regret is that she couldn''t read her favourite character''s ending in an otome game she loved one last time. But after her vision fades to black, she comes to... right in front of said favourite character in the flesh?! It turns out she was reincarnated as the villainess her bias, Albert, is in love with, just as he''s confining her to his manor in his obsession ending!
