INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Obscure Chronicle of Dynasty', 'This is a "fictional, but plausible" strategy role-playing game with a plot which can be regarded as a history of the Three Kingdoms in a different realm. Thus, those who have received little or no attention in the original history may blossom in this very different time and space.' FROM games WHERE igdb_id = 257504 ON CONFLICT (game_id, language_code) DO NOTHING;
