INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Parfum Nostalgique', 'Parfum Nostalgique is a heartfelt tale about the people who change us, for better and for worse. From betrayal to unconditional love, from regret to hope… see the drama unfold between exes and lovers, old friends and new, when you dive into this kinetic visual novel dram-com series. With delicate vintage shoujo-inspired art, original soundtrack, and a diverse cast of voice actors, Parfum Nostalgique is a lovingly handmade passion project packaged with sweets and scented with roses by sole developer Prince Rosalium for your reading pleasure.' FROM games WHERE igdb_id = 259057 ON CONFLICT (game_id, language_code) DO NOTHING;
