INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'They Love Them', 'They Love Them is a romantic match-3 puzzle game. Impress your date by showering them with gifts and affection. Match 3 gifts to send them to your partner. Quickly send gifts to maintain a combo. Play in a relaxing date mode, or rack up points as quickly as you can in the Speed dating mode!' FROM games WHERE igdb_id = 235813 ON CONFLICT (game_id, language_code) DO NOTHING;
