INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You''ll Stay Here Forever', 'Proxima Centauri b was discovered on August 24, 2016. The rovers sent to the planet are not responding. It turned out that the planet''s atmosphere does not allow radio signals to pass through. You have been sent to the planet''s surface to find them.' FROM games WHERE igdb_id = 250346 ON CONFLICT (game_id, language_code) DO NOTHING;
