INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('puzzle-by-nikoli-w-heyawake', 230827, '2023-01-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co61j6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar226d.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzle by Nikoli W Heyawake', 'This is a progressive puzzle which you can comfortably enjoy working out using logic. "Heyawake" is a puzzle in which you fill in the spaces according to the rules. It''s called "heyawake" ("split rooms") because the face of the board is divided into rooms. This puzzle first appeared in 1992, but a plethora of solutions have been developed, allowing for a very progressive puzzle. Each time you discover a new strategic move, your skills of solution will improve.' FROM games WHERE igdb_id = 230827 ON CONFLICT (game_id, language_code) DO NOTHING;
