INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shitataru Nikki', 'Shitataru Nikki is an exploration of the thoughts and mind of the most deplorable and sickening human being possible. You play as Keko, a criminal hiding from the law, as he holes himself up in a dingy hotel room and waits for the heat to die down.
