INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stop Burying Me Alive, Beautiful!', 'You wake up to your girlfriend burying you alive, and she won’t be convinced that you aren’t actually dead- one of several problems, it turns out, as you find yourself dealing with rats trying to take a few early bites out of you! And just who is the girl talking to you from underground?' FROM games WHERE igdb_id = 270154 ON CONFLICT (game_id, language_code) DO NOTHING;
