INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neko Secret Homecoming Light', 'Explore Neko Town looking for hidden objects. Walk down the streets, find new places to get in. Try a variety of mini games like playing darts, picking locks, breaking safes! Try changing your style using character customization. Finally, find the way to get to the anime factory and hack all its computer''s data!' FROM games WHERE igdb_id = 251450 ON CONFLICT (game_id, language_code) DO NOTHING;
