INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gem Worlds', 'Gem World is a roguelike-puzzle hybrid. Explore 100 levels in 10 unique worlds. Dodge boulders, collect gems, fight (or avoid) monsters. Unlock and upgrade more than 20 diverse skills across multiple runs. Exploit obstacles like mines, teleporters, and more. Turn-based and easy to play.' FROM games WHERE igdb_id = 190026 ON CONFLICT (game_id, language_code) DO NOTHING;
