INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cienie', 'Cienie is a mystery-thriller visual novel with supernatural elements set in the Polish town of Sypniewo. You follow Tomasz Tyszko, a law university dropout who now interns at a private investigation agency run by Markus Waldner. After five individuals are reported missing in the town, Tom tries to unravel the mystery behind the disappearances while navigating the complexities of relationships and adulthood.' FROM games WHERE igdb_id = 305251 ON CONFLICT (game_id, language_code) DO NOTHING;
