INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hooligan Simulator 2023: You vs. System', 'In Hooligan Simulator, players are not subjected to trials but are presented with the audacious opportunity to express themselves through graffiti. Armed with the means to draw, you can assert your presence in society through free expression. By painting graffiti, vandalising public property, and leaving your mark, you become the embodiment of audacity. However, be aware that such actions make you a prime target for law enforcement.' FROM games WHERE igdb_id = 277917 ON CONFLICT (game_id, language_code) DO NOTHING;
