INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Exchange Student', 'Exchange Student is an exciting visual novel for adults only, full of unexpected twists and unforgettable moments. You''ll take on the role of James, a young student who decides to make a fresh start by moving to a new city and embarking on his university studies.' FROM games WHERE igdb_id = 252247 ON CONFLICT (game_id, language_code) DO NOTHING;
