INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ugly Button Adventure', 'The Ugly Button Adventure is a classic example of point and click and escape room adventure games that are loved by many gamers around the world. Players will have to solve puzzles and interact with different objects in the game to progress and escape from the unknown room. If you are a fan of escape room games, then Ugly Button Adventure will be right up your alley. It has all the elements that make escape rooms so thrilling, such as hidden clues, puzzles, and a sense of urgency to escape.' FROM games WHERE igdb_id = 273853 ON CONFLICT (game_id, language_code) DO NOTHING;
