INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Celebrating Pani Puri', 'July 12th 2023’s interactive game Doodle celebrates pani puri — a popular South Asian street food made of a crispy shell stuffed with potatoes, chickpeas, spices, or chilis and flavoured waters. And there’s a variety of pani puri for everyone’s taste buds! On this day in 2015, in Indore, Madhya Pradesh, a restaurant called Indori Zayka and Dainik Bhaskar achieved the World Record for serving the most flavors of pani puri by offering 51 options, under the guidance of Masterchef Neha Shah.' FROM games WHERE igdb_id = 256370 ON CONFLICT (game_id, language_code) DO NOTHING;
