INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Return to Bloody Nights', 'Get ready for a spine-tingling lore focused experience with our new fnaf fan game, "Return to Bloody Nights." Inspired by FNaF Plus, the original 4 FNaF games, and the books by Scott Cawthon, this game takes its own unique twist on the timeline and crucial events of the Five Nights at Freddy''s series. With a combination of old-style atmosphere and gameplay, along with new mechanics, our game brings the best elements of the official games to the table. It''s a reborn version of our previous game, "Bloody Nights at Freddy''s."' FROM games WHERE igdb_id = 244000 ON CONFLICT (game_id, language_code) DO NOTHING;
