INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzle by Nikoli S Yajilin', 'Draw lines through the centers of cells to make a loop, and paint cells black in this original Nikoli puzzle. It''s immensely satisfying to see how the lines and black cells all come together to form a solution, and figuring out how to draw the loop isn''t as easy as it might seem.' FROM games WHERE igdb_id = 252622 ON CONFLICT (game_id, language_code) DO NOTHING;
