INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Camphor', 'A short ''bitsy poem'' about my feelings towards fireflies. Made in the span of around 2 hours on a whim on the 9th of February, 2023. Plays for 30 seconds to a minute. Inspired by a recent listen to ''The Campfire Headphase'' by Boards of Canada. You play as a worm in a forest swerving through rocks and trees to see fireflies.' FROM games WHERE igdb_id = 237352 ON CONFLICT (game_id, language_code) DO NOTHING;
