INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beggar''s Paradise', 'Join the adventure in Beggar''s Paradise, the ultimate idle clicker game. Upgrade your items and progress through the levels by tapping and earning money. Build your own economy and watch it grow as you become the richest beggar in the land. Simple, fun and addictive! Beggar''s Paradise will keep you entertained for hours. Download now and see for yourself why it''s the ultimate time-killer game!' FROM games WHERE igdb_id = 272061 ON CONFLICT (game_id, language_code) DO NOTHING;
